if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => {
        navigator.serviceWorker.register("./service-worker.js")
            .then(() => {
                window.dispatchEvent(new Event("thai-quest-service-worker-ready"));
            })
            .catch(error => {
                console.error("Service Worker konnte nicht registriert werden:", error);
                window.dispatchEvent(new CustomEvent("thai-quest-service-worker-error", { detail: error }));
            });
    }, { once: true });
}

const dailyReminderMessages = [
    "Fünf Minuten Thai genügen heute. Bereit für eine kleine Runde?",
    "Zeit für deinen täglichen Ton-Moment: Welches Wort klingt heute anders?",
    "Ein paar Wörter, ein großer Fortschritt. Deine Thai-Übung wartet auf dich.",
    "Mini-Challenge: Sprich heute ein Wort mit fallendem Ton laut aus.",
    "สวัสดี! Dein Thai lernt sich am besten in kleinen täglichen Schritten.",
    "Schon kurz geübt? Trainiere heute einen Ton und halte deine Serie am Leben.",
    "Dein nächstes Lernpaket ist nur eine kurze Übung entfernt.",
    "Hör genau hin: Ein anderer Ton kann im Thai ein anderes Wort bedeuten."
];

const dailyReminderStorageKey = "thai_quest_daily_reminder";
let dailyReminderTimer = null;
let dailyReminderInProgress = false;
let dailyReminderSettings;

try {
    dailyReminderSettings = JSON.parse(localStorage.getItem(dailyReminderStorageKey) || "null") || {
        enabled: false,
        time: "19:00",
        lastReminderDate: "",
        messageIndex: 0
    };
} catch (error) {
    console.error("Die gespeicherte Erinnerungseinstellung konnte nicht gelesen werden:", error);
    dailyReminderSettings = { enabled: false, time: "19:00", lastReminderDate: "", messageIndex: 0 };
}

if (!dailyReminderSettings || typeof dailyReminderSettings !== "object" || Array.isArray(dailyReminderSettings)) {
    dailyReminderSettings = { enabled: false, time: "19:00", lastReminderDate: "", messageIndex: 0 };
}
dailyReminderSettings.enabled = dailyReminderSettings.enabled === true;
dailyReminderSettings.time = /^\d{2}:\d{2}$/.test(dailyReminderSettings.time || "")
    ? dailyReminderSettings.time
    : "19:00";
dailyReminderSettings.lastReminderDate = typeof dailyReminderSettings.lastReminderDate === "string"
    ? dailyReminderSettings.lastReminderDate
    : "";
dailyReminderSettings.messageIndex = Number.isInteger(dailyReminderSettings.messageIndex) && dailyReminderSettings.messageIndex >= 0
    ? dailyReminderSettings.messageIndex % dailyReminderMessages.length
    : 0;

function saveDailyReminderSettings() {
    try {
        localStorage.setItem(dailyReminderStorageKey, JSON.stringify(dailyReminderSettings));
        return true;
    } catch (error) {
        console.error("Die Erinnerungseinstellung konnte nicht gespeichert werden:", error);
        dailyReminderStatus("Die Einstellung konnte nicht gespeichert werden. Prüfe den freien Gerätespeicher.", true);
        return false;
    }
}

function localDateKey(date) {
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function dailyReminderStatus(message, isError = false) {
    const status = document.getElementById("daily-reminder-status");
    if (!status) return;
    status.textContent = message;
    status.classList.toggle("reminder-error", isError);
}

async function deliverDailyReminder() {
    if (dailyReminderInProgress || !dailyReminderSettings.enabled || !("Notification" in window) || Notification.permission !== "granted") {
        return;
    }

    const now = new Date();
    const today = localDateKey(now);
    const [hours, minutes] = dailyReminderSettings.time.split(":").map(Number);
    if (now.getHours() < hours || (now.getHours() === hours && now.getMinutes() < minutes)) {
        scheduleDailyReminder();
        return;
    }
    if (dailyReminderSettings.lastReminderDate === today) return;

    dailyReminderInProgress = true;
    let reminderDelivered = false;
    const messageIndex = Number(dailyReminderSettings.messageIndex) % dailyReminderMessages.length;
    const message = dailyReminderMessages[messageIndex];
    try {
        if ("serviceWorker" in navigator) {
            const registration = await navigator.serviceWorker.ready;
            await registration.showNotification("Thai Tonal Quest 🇹🇭", {
                body: message,
                icon: "./icon.svg",
                badge: "./icon.svg",
                tag: "thai-tonal-quest-daily",
                data: { url: window.location.href }
            });
        } else {
            new Notification("Thai Tonal Quest 🇹🇭", { body: message, tag: "thai-tonal-quest-daily" });
        }

        reminderDelivered = true;
        dailyReminderSettings.lastReminderDate = today;
        dailyReminderSettings.messageIndex = (messageIndex + 1) % dailyReminderMessages.length;
        if (!saveDailyReminderSettings()) return;
        dailyReminderStatus(`Erledigt für heute – morgen gibt es eine neue Erinnerung. (${dailyReminderSettings.time})`);
    } catch (error) {
        console.error("Die tägliche Erinnerung konnte nicht angezeigt werden:", error);
        dailyReminderStatus("Die Benachrichtigung konnte nicht angezeigt werden. Prüfe die Browser-Berechtigung und Systemeinstellungen.", true);
        dailyReminderTimer = window.setTimeout(() => void deliverDailyReminder(), 5 * 60 * 1000);
    } finally {
        dailyReminderInProgress = false;
        if (reminderDelivered) scheduleDailyReminder();
    }
}

function scheduleDailyReminder() {
    window.clearTimeout(dailyReminderTimer);
    if (!dailyReminderSettings.enabled || !("Notification" in window) || Notification.permission !== "granted") {
        return;
    }

    const timeMatch = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(dailyReminderSettings.time);
    if (!timeMatch) {
        dailyReminderStatus("Bitte wähle eine gültige Uhrzeit.", true);
        return;
    }

    const hours = Number(timeMatch[1]);
    const minutes = Number(timeMatch[2]);
    const now = new Date();
    const scheduled = new Date(now);
    scheduled.setHours(hours, minutes, 0, 0);
    const today = localDateKey(now);

    if (scheduled <= now && dailyReminderSettings.lastReminderDate !== today) {
        void deliverDailyReminder();
        return;
    }
    if (scheduled <= now) scheduled.setDate(scheduled.getDate() + 1);

    dailyReminderTimer = window.setTimeout(() => {
        dailyReminderTimer = null;
        scheduleDailyReminder();
    }, Math.max(0, scheduled.getTime() - now.getTime()));
    dailyReminderStatus(`Tägliche Erinnerung ist für ${dailyReminderSettings.time} Uhr aktiviert.`);
}

function setupDailyReminderUI() {
    const nav = document.querySelector(".nav-tabs");
    const app = document.querySelector(".container");
    if (!nav || !app) return;

    const style = document.createElement("style");
    style.textContent = `
        .nav-tabs { flex-wrap: wrap; }
        .nav-btn { min-width: calc(33.333% - 8px); }
        .reminder-card { text-align: left; }
        .reminder-card h3 { margin-top: 0; }
        .reminder-card p { color: #cbd5e1; line-height: 1.55; }
        .reminder-time { display: grid; gap: 8px; margin: 20px 0; }
        .reminder-time input { box-sizing: border-box; width: 100%; padding: 12px; color: #f8fafc; background: #0f172a; border: 1px solid #475569; border-radius: 10px; font: inherit; }
        .reminder-actions { display: flex; flex-wrap: wrap; gap: 10px; }
        .reminder-note { padding: 12px; border-left: 3px solid #f59e0b; background: #0f172a; font-size: .9rem; }
        #daily-reminder-status { min-height: 1.5em; color: #38bdf8; }
        #daily-reminder-status.reminder-error { color: #fca5a5; }
    `;
    document.head.appendChild(style);

    const section = document.createElement("section");
    section.id = "section-reminders";
    section.className = "hidden";
    section.innerHTML = `
        <div class="card reminder-card">
            <h3>⏰ Tägliche Erinnerung</h3>
            <p>Wähle eine Uhrzeit, zu der dich ein abwechslungsreicher kleiner Thai-Impuls an deine Übung erinnert.</p>
            <label class="reminder-time" for="daily-reminder-time">
                <span>Deine Uhrzeit</span>
                <input id="daily-reminder-time" type="time" value="19:00">
            </label>
            <div class="reminder-actions">
                <button id="daily-reminder-enable" class="action-btn btn-primary" type="button">Erinnerung aktivieren</button>
                <button id="daily-reminder-disable" class="action-btn" type="button">Deaktivieren</button>
            </div>
            <p id="daily-reminder-status" role="status" aria-live="polite"></p>
            <p class="reminder-note"><strong>Wichtig:</strong> Die Erinnerung wird lokal im Browser geplant. Sie funktioniert nur, solange die App geöffnet ist; Energiesparfunktionen können sie verzögern. Wenn die App geschlossen ist, kann GitHub Pages keine Push-Nachricht senden. Eine verpasste Erinnerung wird beim nächsten Öffnen nachgeholt.</p>
        </div>
    `;
    app.insertBefore(section, document.getElementById("section-train"));

    const tab = document.createElement("button");
    tab.type = "button";
    tab.className = "nav-btn";
    tab.textContent = "⏰ Erinnerung";
    tab.setAttribute("aria-controls", section.id);
    nav.appendChild(tab);

    const originalSwitchTab = window.switchTab;
    window.switchTab = function switchAppTabWithReminders(name) {
        section.classList.add("hidden");
        if (name !== "reminders") {
            originalSwitchTab(name);
            return;
        }
        document.querySelectorAll(".nav-btn").forEach(button => button.classList.remove("active"));
        document.querySelectorAll("#section-train, #section-exam, #section-lessons, #section-add")
            .forEach(panel => panel.classList.add("hidden"));
        tab.classList.add("active");
        section.classList.remove("hidden");
        document.getElementById("mode-subtitle").textContent = "Deine tägliche Thai-Erinnerung";
    };
    tab.addEventListener("click", () => window.switchTab("reminders"));

    const timeInput = document.getElementById("daily-reminder-time");
    const enableButton = document.getElementById("daily-reminder-enable");
    const disableButton = document.getElementById("daily-reminder-disable");
    timeInput.value = dailyReminderSettings.time || "19:00";

    enableButton.addEventListener("click", async () => {
        const selectedTime = timeInput.value;
        if (!/^([01]\d|2[0-3]):([0-5]\d)$/.test(selectedTime)) {
            dailyReminderStatus("Bitte wähle eine gültige Uhrzeit.", true);
            return;
        }
        if (!window.isSecureContext || !("Notification" in window)) {
            dailyReminderStatus("Benachrichtigungen benötigen einen unterstützten Browser und eine sichere HTTPS-Verbindung.", true);
            return;
        }
        if (Notification.permission !== "granted") {
            let permission;
            try {
                permission = await Notification.requestPermission();
            } catch (error) {
                console.error("Die Benachrichtigungsberechtigung konnte nicht angefragt werden:", error);
                dailyReminderStatus("Die Berechtigung konnte nicht angefragt werden. Prüfe die Browser-Einstellungen.", true);
                return;
            }
            if (permission !== "granted") {
                dailyReminderStatus(permission === "denied"
                    ? "Benachrichtigungen sind im Browser blockiert. Erlaube sie in den Android- oder Website-Einstellungen."
                    : "Ohne Benachrichtigungsberechtigung kann ich dich nicht erinnern.", true);
                return;
            }
        }

        const previousSettings = { enabled: dailyReminderSettings.enabled, time: dailyReminderSettings.time };
        dailyReminderSettings.enabled = true;
        dailyReminderSettings.time = selectedTime;
        if (!saveDailyReminderSettings()) {
            Object.assign(dailyReminderSettings, previousSettings);
            return;
        }
        scheduleDailyReminder();
    });

    timeInput.addEventListener("change", () => {
        const selectedTime = timeInput.value;
        if (!/^([01]\d|2[0-3]):([0-5]\d)$/.test(selectedTime)) {
            timeInput.value = dailyReminderSettings.time;
            dailyReminderStatus("Bitte wähle eine gültige Uhrzeit.", true);
            return;
        }
        const previousTime = dailyReminderSettings.time;
        dailyReminderSettings.time = selectedTime;
        if (!saveDailyReminderSettings()) {
            dailyReminderSettings.time = previousTime;
            timeInput.value = previousTime;
            return;
        }
        if (dailyReminderSettings.enabled) scheduleDailyReminder();
    });

    disableButton.addEventListener("click", () => {
        const wasEnabled = dailyReminderSettings.enabled;
        dailyReminderSettings.enabled = false;
        if (!saveDailyReminderSettings()) {
            dailyReminderSettings.enabled = wasEnabled;
            return;
        }
        window.clearTimeout(dailyReminderTimer);
        dailyReminderStatus("Die tägliche Erinnerung ist ausgeschaltet.");
    });

    if (!window.isSecureContext || !("Notification" in window)) {
        enableButton.disabled = true;
        dailyReminderStatus("Benachrichtigungen sind hier nicht verfügbar. Öffne die App über HTTPS in einem unterstützten Browser.", true);
    } else if (Notification.permission === "denied") {
        dailyReminderStatus("Benachrichtigungen sind im Browser blockiert. Erlaube sie in den Android- oder Website-Einstellungen.", true);
    } else if (dailyReminderSettings.enabled && Notification.permission === "granted") {
        scheduleDailyReminder();
    } else {
        dailyReminderStatus("Noch ausgeschaltet. Die Benachrichtigungserlaubnis wird erst beim Aktivieren angefragt.");
    }

    const refreshReminder = () => {
        if (dailyReminderSettings.enabled && document.visibilityState === "visible") scheduleDailyReminder();
    };
    document.addEventListener("visibilitychange", refreshReminder);
    window.addEventListener("focus", refreshReminder);
}

